namespace {
struct Failure { int code; };
struct Kernel { const double *weights; size_t count; };
struct SpatialPreset {
    const char *key;
    bool grain;
    double amount, color, roughness, usm_amount, usm_threshold;
    Kernel fine, coarse, usm;
};
struct NativeSharpnessPreset {
    const char* key;
    bool enabled;
    int amount;
    double radius;
    int noise, dark;
};
#include "hncs_spatial_assets.inc"
constexpr size_t kChunk=65536, kTile=4096;

struct Operation {
    const char *directory;
    hncs_spatial_cancel_fn callback;
    void *context;
    void check() const { if(callback && callback(context)) throw Failure{-3}; }
};

class Store {
public:
    virtual ~Store()=default;
    virtual void read(size_t offset,float *p,size_t n)=0;
    virtual void write(size_t offset,const float *p,size_t n)=0;
};
class Memory final:public Store {
    float *data_;
public:
    explicit Memory(float *data):data_(data){}
    void read(size_t o,float *p,size_t n) override {std::memcpy(p,data_+o,n*sizeof(float));}
    void write(size_t o,const float *p,size_t n) override {std::memcpy(data_+o,p,n*sizeof(float));}
};
class File final:public Store {
    FILE *file_=nullptr;
    size_t position_=0;
    char last_=0;
    void seek(size_t offset,char mode) {
        if(last_!=mode || position_!=offset) {
            if(fseeko(file_,static_cast<off_t>(offset*sizeof(float)),SEEK_SET))throw Failure{-2};
        }
        last_=mode;position_=offset;
    }
public:
    explicit File(const char *path,size_t samples) {
        file_=std::fopen(path,"r+b");if(!file_)throw Failure{-2};
        struct stat st{};
        if(fstat(fileno(file_),&st) || !S_ISREG(st.st_mode) || st.st_size<0 ||
            static_cast<uint64_t>(st.st_size)!=static_cast<uint64_t>(samples)*sizeof(float)) {
            std::fclose(file_);file_=nullptr;throw Failure{-1};
        }
    }
    explicit File(const Operation& op) {
        if(op.directory && op.directory[0]) {
            std::string path=std::string(op.directory)+"/hncs-spatial-XXXXXX";
            std::vector<char> mutable_path(path.begin(),path.end());mutable_path.push_back(0);
            const int fd=mkstemp(mutable_path.data());if(fd<0)throw Failure{-2};
            if(unlink(mutable_path.data())) {close(fd);throw Failure{-2};}
            file_=fdopen(fd,"w+b");if(!file_) {close(fd);throw Failure{-2};}
        } else file_=std::tmpfile();
        if(!file_)throw Failure{-2};
    }
    ~File() override {if(file_)std::fclose(file_);}
    void read(size_t o,float *p,size_t n) override {
        seek(o,'r');if(std::fread(p,sizeof(float),n,file_)!=n)throw Failure{-2};position_+=n;
    }
    void write(size_t o,const float *p,size_t n) override {
        seek(o,'w');if(std::fwrite(p,sizeof(float),n,file_)!=n)throw Failure{-2};position_+=n;
    }
    void flush() {if(std::fflush(file_))throw Failure{-2};}
};

std::string canonical(const char *key) {
    std::string s=key?key:"standard";
    const auto first=s.find_first_not_of(" \t\r\n"),last=s.find_last_not_of(" \t\r\n");
    s=first==std::string::npos?"":s.substr(first,last-first+1);
    for(char &c:s)if(c>='A'&&c<='Z')c=static_cast<char>(c+'a'-'A');
    for(const char *dash:{"\xe2\x80\x93","\xe2\x80\x94"}) {
        size_t i=0;while((i=s.find(dash,i))!=std::string::npos)s.replace(i,3,"-");
    }
    if(s=="default")s="standard";
    else if(s=="extra contrast")s="extra-contrast";
    else if(s=="square crop")s="square-crop";
    return s;
}
const SpatialPreset& preset(const char *key) {
    const std::string k=canonical(key);
    for(const auto &p:kSpatialPresets)if(k==p.key)return p;
    throw Failure{-1};
}
size_t dimensions(size_t w,size_t h,int grain,int sharp) {
    if(!w||!h||(grain!=0&&grain!=1)||(sharp!=0&&sharp!=1) ||
       w>std::numeric_limits<size_t>::max()/h)throw Failure{-1};
    const size_t n=w*h;
    if(n>std::numeric_limits<size_t>::max()/(3*sizeof(float)) ||
       n>static_cast<uint64_t>(std::numeric_limits<off_t>::max())/(3*sizeof(float)) ||
       w>static_cast<size_t>(INT64_MAX/2) || h>static_cast<size_t>(INT64_MAX/2))throw Failure{-1};
    return n;
}

// SHA-256 of the exact Python f"{key}:{(height, width, 3)}" UTF-8 string.
// FIPS 180-4 compression, byte serialization specified explicitly.
uint32_t rotate(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
uint64_t seed_for(const char *key,size_t w,size_t h) {
    const std::string text=std::string(key)+":("+std::to_string(h)+", "+std::to_string(w)+", 3)";
    std::vector<uint8_t> bytes(text.begin(),text.end());
    const uint64_t bits=static_cast<uint64_t>(bytes.size())*8;
    bytes.push_back(0x80);while(bytes.size()%64!=56)bytes.push_back(0);
    for(int i=7;i>=0;--i)bytes.push_back(static_cast<uint8_t>(bits>>(i*8)));
    static constexpr uint32_t k[]={
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
    uint32_t state[]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for(size_t start=0;start<bytes.size();start+=64) {
        uint32_t words[64];
        for(size_t i=0;i<16;++i){words[i]=0;for(size_t j=0;j<4;++j)words[i]=(words[i]<<8)|bytes[start+i*4+j];}
        for(size_t i=16;i<64;++i){const uint32_t x=words[i-15],y=words[i-2];words[i]=words[i-16]+(rotate(x,7)^rotate(x,18)^(x>>3))+words[i-7]+(rotate(y,17)^rotate(y,19)^(y>>10));}
        uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h0=state[7];
        for(size_t i=0;i<64;++i){const uint32_t t=h0+(rotate(e,6)^rotate(e,11)^rotate(e,25))+((e&f)^(~e&g))+k[i]+words[i];const uint32_t u=(rotate(a,2)^rotate(a,13)^rotate(a,22))+((a&b)^(a&c)^(b&c));h0=g;g=f;f=e;e=d+t;d=c;c=b;b=a;a=t+u;}
        state[0]+=a;state[1]+=b;state[2]+=c;state[3]+=d;state[4]+=e;state[5]+=f;state[6]+=g;state[7]+=h0;
    }
    uint64_t result=0;
    for(unsigned i=0;i<8;++i)result|=static_cast<uint64_t>((state[i/4]>>(24-8*(i%4)))&255)<<(8*i);
    return result;
}

size_t boundary(int64_t index,size_t count,bool wrap) {
    const int64_t length=static_cast<int64_t>(count);
    if(wrap){index%=length;if(index<0)index+=length;return static_cast<size_t>(index);}
    return static_cast<size_t>(std::max<int64_t>(0,std::min<int64_t>(index,length-1)));
}
void gaussian(Store &input,Store &output,size_t width,size_t height,
              Kernel kernel,bool wrap,const Operation &op) {
    File intermediate(op);
    const size_t radius=kernel.count/2,ring_count=kernel.count;
    // Axis 0 is rounded to float32 before axis 1, as scipy.ndimage does.
    for(size_t left=0;left<width;left+=kTile) {
        const size_t n=std::min(kTile,width-left);
        std::vector<float> ring(ring_count*n),out(n);
        for(size_t j=0;j<ring_count;++j)input.read(boundary(static_cast<int64_t>(j)-static_cast<int64_t>(radius),height,wrap)*width+left,ring.data()+j*n,n);
        size_t first=0;
        for(size_t y=0;y<height;++y) {
            op.check();
            for(size_t x=0;x<n;++x) {
                double sum=static_cast<double>(ring[((first+radius)%ring_count)*n+x])*kernel.weights[radius];
                for(size_t j=0;j<radius;++j)sum+=(static_cast<double>(ring[((first+j)%ring_count)*n+x])+static_cast<double>(ring[((first+ring_count-1-j)%ring_count)*n+x]))*kernel.weights[j];
                out[x]=static_cast<float>(sum);
            }
            intermediate.write(y*width+left,out.data(),n);
            if(y+1<height)input.read(boundary(static_cast<int64_t>(y)+static_cast<int64_t>(radius)+1,height,wrap)*width+left,ring.data()+first*n,n);
            first=(first+1)%ring_count;
        }
    }
    std::vector<float> extended(kTile+2*radius),out(kTile);
    for(size_t y=0;y<height;++y)for(size_t left=0;left<width;left+=kTile) {
        op.check();const size_t n=std::min(kTile,width-left);
        // Only the halo needs per-value boundary lookup; the interior is contiguous.
        intermediate.read(y*width+left,extended.data()+radius,n);
        for(size_t j=0;j<radius;++j) {
            intermediate.read(y*width+boundary(static_cast<int64_t>(left)+static_cast<int64_t>(j)-static_cast<int64_t>(radius),width,wrap),extended.data()+j,1);
            intermediate.read(y*width+boundary(static_cast<int64_t>(left+n+j),width,wrap),extended.data()+radius+n+j,1);
        }
        for(size_t x=0;x<n;++x) {
            double sum=static_cast<double>(extended[x+radius])*kernel.weights[radius];
            for(size_t j=0;j<radius;++j)sum+=(static_cast<double>(extended[x+j])+static_cast<double>(extended[x+2*radius-j]))*kernel.weights[j];
            out[x]=static_cast<float>(sum);
        }
        output.write(y*width+left,out.data(),n);
    }
}

class Reader {
    Store &store_;size_t total_,start_=0,length_=0;std::vector<float> cache_;
public:
    Reader(Store &s,size_t n):store_(s),total_(n),cache_(kChunk){}
    float operator()(size_t i){if(i<start_||i>=start_+length_){start_=i;length_=std::min(kChunk,total_-i);store_.read(start_,cache_.data(),length_);}return cache_[i-start_];}
};
// NumPy's contiguous float32 reduction tree: 128-value leaves, eight lanes.
// Keep this separate from the sequential reduction of an interleaved RGB axis.
template<class Value> float pairwise(Value &value,size_t start,size_t count,const Operation &op) {
    if(count<8){float s=-0.f;for(size_t i=0;i<count;++i)s+=value(start+i);return s;}
    if(count<=128){float lane[8];for(size_t i=0;i<8;++i)lane[i]=value(start+i);size_t i=8;for(;i<count-count%8;i+=8)for(size_t j=0;j<8;++j)lane[j]+=value(start+i+j);float s=((lane[0]+lane[1])+(lane[2]+lane[3]))+((lane[4]+lane[5])+(lane[6]+lane[7]));for(;i<count;++i)s+=value(start+i);return s;}
    if(count>kChunk)op.check();
    size_t half=count/2;half-=half%8;
    const float low=pairwise(value,start,half,op),high=pairwise(value,start+half,count-half,op);return low+high;
}
float stddev(Store &store,size_t n,bool sequential,const Operation &op) {
    Reader reader(store,n);auto identity=[&](size_t i){return reader(i);};float sum=0;
    if(sequential){for(size_t i=0;i<n;++i){if(i%kChunk==0)op.check();sum+=reader(i);}}
    else sum=pairwise(identity,0,n,op);
    const float mean=static_cast<float>(static_cast<double>(sum)/static_cast<double>(n));
    Reader reader2(store,n);auto square=[&](size_t i){float d=reader2(i)-mean;return d*d;};
    sum=0;
    if(sequential){for(size_t i=0;i<n;++i){if(i%kChunk==0)op.check();sum+=square(i);}}
    else sum=pairwise(square,0,n,op);
    const float variance=static_cast<float>(static_cast<double>(sum)/static_cast<double>(n));
    return std::sqrt(variance);
}
void normals(Store &output,size_t n,hncs_spatial::NumpyNormal &rng,const Operation &op) {
    std::vector<float> buffer(kChunk);
    for(size_t at=0;at<n;at+=kChunk){op.check();const size_t count=std::min(kChunk,n-at);for(size_t j=0;j<count;++j)buffer[j]=rng.next_float();output.write(at,buffer.data(),count);}
}
void normalize(Store &plane,size_t n,float divisor,const Operation &op) {
    std::vector<float> buffer(kChunk);
    for(size_t at=0;at<n;at+=kChunk){op.check();const size_t count=std::min(kChunk,n-at);plane.read(at,buffer.data(),count);for(size_t j=0;j<count;++j)buffer[j]/=divisor;plane.write(at,buffer.data(),count);}
}
float clip(float x){return std::max(0.f,std::min(1.f,x));}
void add_grain(Store &work,Store &grain,Store &channel,size_t n,int which,
               float channel_std,const SpatialPreset &cfg,const Operation &op) {
    std::vector<float> rgb(kChunk*3),g(kChunk),c(kChunk);
    const float color=static_cast<float>(cfg.color),mono=static_cast<float>(1.-cfg.color);
    const float amplitude=static_cast<float>(.012*cfg.amount);
    for(size_t at=0;at<n;at+=kChunk) {
        op.check();const size_t count=std::min(kChunk,n-at);
        work.read(at*3,rgb.data(),count*3);grain.read(at,g.data(),count);
        if(which>=0)channel.read(at,c.data(),count);
        for(size_t i=0;i<count;++i) {
            const float noise=which<0?g[i]:(c[i]/channel_std)*color+g[i]*mono;
            const int first=which<0?0:which,last=which<0?3:which+1;
            for(int ch=first;ch<last;++ch) {
                const size_t j=i*3+static_cast<size_t>(ch);
                const float strength=amplitude*(.55f+.45f*std::sqrt(clip(rgb[j])));
                rgb[j]=clip(rgb[j]+noise*strength);
            }
        }
        work.write(at*3,rgb.data(),count*3);
    }
}
void apply_grain(Store &work,size_t w,size_t h,const SpatialPreset &cfg,const Operation &op) {
    const size_t n=w*h;hncs_spatial::NumpyNormal rng(seed_for(cfg.key,w,h));
    File grain(op);
    {
        File base(op),coarse(op);normals(base,n,rng,op);
        gaussian(base,grain,w,h,cfg.fine,true,op);gaussian(base,coarse,w,h,cfg.coarse,true,op);
        std::vector<float> fine(kChunk),rough(kChunk);
        const float fine_amount=static_cast<float>(1.-cfg.roughness),coarse_amount=static_cast<float>(cfg.roughness);
        for(size_t at=0;at<n;at+=kChunk){op.check();const size_t count=std::min(kChunk,n-at);grain.read(at,fine.data(),count);coarse.read(at,rough.data(),count);for(size_t j=0;j<count;++j)fine[j]=fine_amount*fine[j]+coarse_amount*rough[j];grain.write(at,fine.data(),count);}
    }
    normalize(grain,n,std::max(stddev(grain,n,false,op),1.e-6f),op);
    if(cfg.color==0){add_grain(work,grain,grain,n,-1,1.f,cfg,op);return;}
    add_grain(work,grain,grain,n,0,std::max(stddev(grain,n,true,op),1.e-6f),cfg,op);
    for(int ch=1;ch<3;++ch) {
        File filtered(op);
        {File base(op);normals(base,n,rng,op);gaussian(base,filtered,w,h,cfg.fine,true,op);}
        add_grain(work,grain,filtered,n,ch,std::max(stddev(filtered,n,true,op),1.e-6f),cfg,op);
    }
}
void apply_usm(Store &work,size_t w,size_t h,const SpatialPreset &cfg,const Operation &op) {
    const size_t n=w*h;std::vector<float> rgb(kChunk*3),plane(kChunk),blur(kChunk);
    const float threshold=static_cast<float>(cfg.usm_threshold),amount=static_cast<float>(cfg.usm_amount);
    for(size_t ch=0;ch<3;++ch) {
        File input(op),filtered(op);
        for(size_t at=0;at<n;at+=kChunk){op.check();const size_t count=std::min(kChunk,n-at);work.read(at*3,rgb.data(),count*3);for(size_t j=0;j<count;++j)plane[j]=rgb[j*3+ch];input.write(at,plane.data(),count);}
        gaussian(input,filtered,w,h,cfg.usm,false,op);
        for(size_t at=0;at<n;at+=kChunk){op.check();const size_t count=std::min(kChunk,n-at);work.read(at*3,rgb.data(),count*3);filtered.read(at,blur.data(),count);for(size_t j=0;j<count;++j){const size_t k=j*3+ch;float detail=rgb[k]-blur[j];if(threshold!=0.f&&std::abs(detail)<threshold)detail=0.f;rgb[k]=clip(rgb[k]+amount*detail);}work.write(at*3,rgb.data(),count*3);}
    }
}
void process(Store &work,size_t w,size_t h,const SpatialPreset &cfg,int grain,int sharp,const Operation &op) {
    std::vector<float> buffer(kChunk);const size_t samples=w*h*3;
    for(size_t at=0;at<samples;at+=kChunk){op.check();const size_t n=std::min(kChunk,samples-at);work.read(at,buffer.data(),n);for(size_t j=0;j<n;++j)if(!std::isfinite(buffer[j]))throw Failure{-1};}
    if(grain&&cfg.grain)apply_grain(work,w,h,cfg,op);
    if(sharp&&cfg.usm_amount!=0)apply_usm(work,w,h,cfg,op);
    op.check();
}

uint16_t native_work_code(float value) {
    const double scaled=double(clip(value)*65535.f);
    const double floor=std::floor(scaled),fraction=scaled-floor;
    return uint16_t(floor+((fraction>.5||(fraction==.5&&std::fmod(floor,2.)!=0.))?1.:0.));
}

void apply_native_usm(Store &work,size_t w,size_t h,const NativeSharpnessPreset &cfg,
                      double baseline,const Operation &op) {
    const hncs_phocus_sharpness::Context kernel(cfg.amount,cfg.radius,cfg.noise,cfg.dark,baseline);
    const size_t radius=kernel.radius();
    // One immutable horizontal-luma plane makes in-place output safe across
    // tile boundaries. Integer luma <=16383 is exactly represented by Float32.
    // Scratch: 4 bytes/pixel; working buffers are independent of image shape.
    File horizontal(op);
    std::vector<float> rgb((kTile+8)*3),plane(kTile+8),filtered(kTile);
    std::vector<uint16_t> luma(kTile+8);
    std::vector<uint32_t> sum(kTile);
    for(size_t y=0;y<h;++y)for(size_t x=0;x<w;x+=kTile) {
        op.check();const size_t count=std::min(kTile,w-x);
        const size_t left=x>radius?x-radius:0,right=x+count+std::min(radius,w-x-count);
        work.read((y*w+left)*3,rgb.data(),(right-left)*3);
        for(size_t j=0;j<right-left;++j) {
            const uint16_t codes[3]={native_work_code(rgb[j*3]),native_work_code(rgb[j*3+1]),native_work_code(rgb[j*3+2])};
            luma[j]=kernel.luma(codes);
        }
        for(size_t j=0;j<count;++j) {
            uint32_t value=0;const size_t position=x+j;
            for(unsigned k=0;k<kernel.count;++k) {
                const size_t sx=k<radius?(position<radius-k?0:position-(radius-k)):
                    position+std::min(size_t(k)-radius,w-1-position);
                value+=kernel.weights[k]*luma[sx-left];
            }
            filtered[j]=float(value/kernel.weight_sum);
        }
        horizontal.write(y*w+x,filtered.data(),count);
    }
    for(size_t y=0;y<h;++y)for(size_t x=0;x<w;x+=kTile) {
        op.check();const size_t count=std::min(kTile,w-x);
        std::fill(sum.begin(),sum.begin()+count,0u);
        for(unsigned k=0;k<kernel.count;++k) {
            const size_t sy=k<radius?(y<radius-k?0:y-(radius-k)):y+std::min(size_t(k)-radius,h-1-y);
            horizontal.read(sy*w+x,plane.data(),count);
            for(size_t j=0;j<count;++j)sum[j]+=kernel.weights[k]*uint32_t(plane[j]);
        }
        work.read((y*w+x)*3,rgb.data(),count*3);
        for(size_t j=0;j<count;++j) {
            const uint16_t source[3]={native_work_code(rgb[j*3]),native_work_code(rgb[j*3+1]),native_work_code(rgb[j*3+2])};
            uint16_t destination[3];kernel.finish(source,uint16_t(sum[j]/kernel.weight_sum),destination);
            for(unsigned ch=0;ch<3;++ch)rgb[j*3+ch]=float(destination[ch])/65535.f;
        }
        work.write((y*w+x)*3,rgb.data(),count*3);
    }
}

void process_native_sharpness(Store &work,size_t w,size_t h,const SpatialPreset &cfg,
                              int grain,int sharp,double baseline,const Operation &op) {
    if(!std::isfinite(baseline)||baseline<0.)throw Failure{-1};
    const NativeSharpnessPreset* native=nullptr;
    for(const auto& row:kNativeSharpnessPresets)if(std::strcmp(row.key,cfg.key)==0){native=&row;break;}
    if(!native)throw Failure{-1};
    std::vector<float> buffer(kChunk);const size_t samples=w*h*3;
    for(size_t at=0;at<samples;at+=kChunk){op.check();const size_t n=std::min(kChunk,samples-at);work.read(at,buffer.data(),n);for(size_t j=0;j<n;++j)if(!std::isfinite(buffer[j]))throw Failure{-1};}
    if(sharp&&native->enabled&&hncs_phocus_sharpness::effective_amount(native->amount,baseline)>0.)
        apply_native_usm(work,w,h,*native,baseline,op);
    // Original AddPostViewerRGBFilters puts sharpness before film grain.
    // Grain remains the separately documented portable model.
    if(grain&&cfg.grain)apply_grain(work,w,h,cfg,op);
    op.check();
}
} // namespace

extern "C" int hncs_native_sharpness_enabled(const char *key) {
    if(!key)return -1;
    for(const auto& row:kNativeSharpnessPresets)
        if(std::strcmp(row.key,key)==0)return row.enabled&&row.amount>0?1:0;
    return -1;
}

extern "C" int hncs_apply_spatial_preset(float *work,size_t w,size_t h,const char *key,int grain,int sharp) {
    try{dimensions(w,h,grain,sharp);if(!work)throw Failure{-1};const auto &cfg=preset(key);Memory store(work);process(store,w,h,cfg,grain,sharp,{nullptr,nullptr,nullptr});return 0;}
    catch(const Failure &e){return e.code;}catch(...){return -2;}
}
extern "C" int hncs_apply_spatial_preset_file(const char *path,size_t w,size_t h,const char *key,int grain,int sharp,const char *directory,hncs_spatial_cancel_fn cancelled,void *context) {
    try{const size_t n=dimensions(w,h,grain,sharp);if(!path||!path[0])throw Failure{-1};const auto &cfg=preset(key);File store(path,n*3);process(store,w,h,cfg,grain,sharp,{directory,cancelled,context});store.flush();return 0;}
    catch(const Failure &e){return e.code;}catch(...){return -2;}
}
extern "C" int hncs_apply_spatial_native_sharpness(float *work,size_t w,size_t h,const char *key,int grain,int sharp,double baseline) {
    try{dimensions(w,h,grain,sharp);if(!work)throw Failure{-1};const auto &cfg=preset(key);Memory store(work);process_native_sharpness(store,w,h,cfg,grain,sharp,baseline,{nullptr,nullptr,nullptr});return 0;}
    catch(const Failure &e){return e.code;}catch(const std::invalid_argument&){return -1;}catch(...){return -2;}
}
extern "C" int hncs_apply_spatial_native_sharpness_file(const char *path,size_t w,size_t h,const char *key,int grain,int sharp,double baseline,const char *directory,hncs_spatial_cancel_fn cancelled,void *context) {
    try{const size_t n=dimensions(w,h,grain,sharp);if(!path||!path[0])throw Failure{-1};const auto &cfg=preset(key);File store(path,n*3);process_native_sharpness(store,w,h,cfg,grain,sharp,baseline,{directory,cancelled,context});store.flush();return 0;}
    catch(const Failure &e){return e.code;}catch(const std::invalid_argument&){return -1;}catch(...){return -2;}
}
